package fptu.semester8.mss301.propertiesservice.features.roomtype.application;
import fptu.exe202.signify.apiresponse.exception.*; import fptu.semester8.mss301.propertiesservice.common.id.IdGenerator; import fptu.semester8.mss301.propertiesservice.features.roomtype.api.dto.RoomTypeRequest; import fptu.semester8.mss301.propertiesservice.features.roomtype.domain.RoomType; import fptu.semester8.mss301.propertiesservice.features.roomtype.infrastructure.RoomTypeRepository; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant;
@Service @RequiredArgsConstructor public class RoomTypeService { private final RoomTypeRepository repo; private final IdGenerator ids; @Transactional public RoomType create(RoomTypeRequest r){String n=r.name().trim();if(repo.existsByNameIgnoreCase(n))throw new ConflictException("Room type name already exists","ROOM_TYPE_NAME_CONFLICT");return repo.save(new RoomType(ids.nextId(),n,r.description(),Instant.now()));} @Transactional(readOnly=true) public RoomType get(long id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Room type not found","ROOM_TYPE_NOT_FOUND"));} @Transactional(readOnly=true) public Page<RoomType> list(Pageable p){return repo.findAll(p);} @Transactional public RoomType update(long id,RoomTypeRequest r){RoomType x=get(id);String n=r.name().trim();if(repo.existsByNameIgnoreCase(n)&&!x.getName().equalsIgnoreCase(n))throw new ConflictException("Room type name already exists","ROOM_TYPE_NAME_CONFLICT");x.update(n,r.description(),Instant.now());return repo.save(x);} @Transactional public void delete(long id){repo.delete(get(id));} }
